INSERT INTO `AIChatHistory` VALUES ('01762252-fb5f-4c42-9f17-d36de4317752','1b3482c2-89c8-4a8d-959b-88ae17d0af96',NULL,'assistant',NULL,'SELECT Id, Title, Slug, Price, DiscountPrice, Currency, AvgRating, MinAge FROM Games WHERE Status=\'Published\' LIMIT 0','[]','Dạ, GameVault là nền tảng phân phối game PC hàng đầu, cho phép tải game và chơi thử bản demo WebGL trực tiếp trên trình duyệt. Em sẵn sàng hỗ trợ bạn tìm game nhé!',NULL,NULL,'2026-06-25 05:35:57.234205'),('05889a15-6edc-4e46-a192-78350d1b9ef6','b4bbe390-bc96-45ae-bd5c-9969a27dfd62',NULL,'user','Co bao nhieu game?',NULL,NULL,NULL,NULL,NULL,'2026-06-25 05:19:57.439489'),('1407652c-3653-44e3-9a0d-b94816afced7','0614e8d2-fc2b-4afe-837d-a7b663b38a93',NULL,'user','thong ke he thong: user, game, don hang, doanh thu',NULL,NULL,NULL,NULL,NULL,'2026-06-25 05:38:56.234953'),('15bef070-0fa1-4301-8c51-bb7acb6df427','e9747437-9ec0-4a21-b661-ef1667d74e6e','e976d500-08b2-496b-81c8-c81658333bef','assistant',NULL,'SELECT Id, Title, Slug, Price, DiscountPrice, Currency, AvgRating, MinAge FROM Games WHERE Status=\'Published\' AND COALESCE(DiscountPrice, Price) <= 200000 LIMIT 20','[{\"Id\": \"eeabb071-a748-42d7-96d7-443270baeb1e\", \"Slug\": \"shootv2\", \"Price\": 0.0, \"Title\": \"ShootV2\", \"MinAge\": 0, \"HasDemo\": true, \"Currency\": \"VND\", \"AvgRating\": 4.0, \"IsFeatured\": false, \"ReviewCount\": 0, \"CategoryName\": \"\", \"DiscountPrice\": null, \"DownloadCount\": 0, \"PrimaryImageUrl\": \"/uploads/games/eeabb071-a748-42d7-96d7-443270baeb1e/image/f7ee9459-51de-47df-b30b-27a0dfcfd5c8_ShootV2.png\", \"ShortDescription\": \"\"}, {\"Id\": \"e525e819-ad6a-4e20-a96c-dd9d71185b0c\", \"Slug\": \"shootv1\", \"Price\": 100000.0, \"Title\": \"ShootV1\", \"MinAge\": 0, \"HasDemo\": true, \"Currency\": \"VND\", \"AvgRating\": 0.0, \"IsFeatured\": false, \"ReviewCount\": 0, \"CategoryName\": \"\", \"DiscountPrice\": null, \"DownloadCount\": 0, \"PrimaryImageUrl\": \"/uploads/games/e525e819-ad6a-4e20-a96c-dd9d71185b0c/image/1acc06b1-6cb4-4382-9ce8-71038e341a7c_ShootV1.png\", \"ShortDescription\": \"\"}]','Dạ, em tìm được 2 game dưới 200K nè!',NULL,NULL,'2026-06-25 09:04:51.207083'),('1bc976ef-d30c-405b-9649-804b2669e893','b4bbe390-bc96-45ae-bd5c-9969a27dfd62',NULL,'assistant',NULL,'SELECT g.Id, g.Title, g.Slug, g.Price, g.DiscountPrice, g.Currency, g.AvgRating, g.MinAge FROM Games g WHERE g.Status=\'Published\' LIMIT 0','[]','Tiếc quá, hiện tại kho game của tụi mình chưa có tựa game nào phù hợp với yêu cầu này rồi. Bạn thử tìm đầy đủ tên game hoặc tìm thể loại khác xem sao nha!',NULL,NULL,'2026-06-25 05:18:51.270279'),('23304b34-5a05-4150-8aa3-7bec708278e3','49fcc8b9-8418-4361-addc-2803b5c2fe95','22222222-2222-4222-8222-222222222202','assistant',NULL,'SELECT g.Id, g.Title, g.Slug, g.Price, g.DiscountPrice, g.Currency, g.AvgRating, g.MinAge FROM Games g INNER JOIN GameCategories gc ON g.Id = gc.GameId INNER JOIN Categories c ON gc.CategoryId = c.Id WHERE g.Status=\'Published\' AND c.Slug=\'action\' ORDER BY g.AvgRating DESC LIMIT 20','[{\"Id\": \"eeabb071-a748-42d7-96d7-443270baeb1e\", \"Slug\": \"shootv2\", \"Price\": 0.0, \"Title\": \"ShootV2\", \"MinAge\": 0, \"HasDemo\": true, \"Currency\": \"VND\", \"AvgRating\": 0.0, \"IsFeatured\": false, \"ReviewCount\": 0, \"CategoryName\": \"\", \"DiscountPrice\": null, \"DownloadCount\": 0, \"PrimaryImageUrl\": \"https://drive.google.com/thumbnail?sz=w1000&id=181704U19F-t9jw7pm8TLQvNvEKTurSkI\", \"ShortDescription\": \"\"}]','Em tìm thấy 1 game hành động cực hay và được yêu thích nhất nè!',NULL,NULL,'2026-07-16 18:41:24.602211'),('24f59c09-591c-40ff-adb2-2152396f1b3e','7791ca5c-ef9c-419b-b713-957f869af232',NULL,'assistant',NULL,'INTENT_INTERCEPT','[]','Xin lỗi, thông tin người dùng chỉ dành cho Quản trị viên hệ thống.',NULL,NULL,'2026-06-25 13:56:46.024831'),('278f8b9d-de64-4342-a27b-70e5818722d4','7a5217b8-4e7b-454f-a782-58854c3d347d',NULL,'assistant',NULL,'SELECT g.Id, g.Title, g.Slug, g.Price, g.DiscountPrice, g.Currency, g.AvgRating, g.MinA